if (score >= 90) {
    grade = 'A';
} else if (score >= 80) {
    grade = 'B';
} else {
    grade = 'C';
}

switch (command) {
case 'q':
    running = false;
    break;
case 'h':
    show_help();
    break;
default:
    report_unknown();
    break;
}

size_t i = 0;
while (i < count) {
    if (!is_valid(items[i])) {
        ++i;
        continue;
    }
    process(items[i]);
    ++i;
}
